#include <stdio.h>
int main(void) {
    char name[16];
    /* gets(name);  removed in C11: it cannot limit how much it writes */
    if (fgets(name, sizeof name, stdin))   /* reads at most 15 characters */
        printf("hello %s", name);
    return 0;
}

import struct
horizontal_bias = 40000.0   # a 64-bit float; a signed 16-bit integer holds at most 32767
try:
    struct.pack('<h', int(horizontal_bias))
except struct.error as e:
    print('conversion failed:', e)
